INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 18, 'theory', 'Квиз: multipath, iSCSI и FC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 0, 'Почему одно устройство, видимое через два пути, появляется в системе как два диска, например sdb и sdc?', '["Ядро создаёт отдельный SCSI-диск для каждого пути, а multipathd склеивает их по WWID", "Массив делит LUN пополам между путями", "Ядро всегда делает зеркало из двух путей", "Диск sdc появляется только после перезагрузки"]', 0, 'Каждый путь — отдельное SCSI-устройство со своим именем. Одинаковый WWID говорит, что это одно устройство, и multipathd собирает над путями одну карту в /dev/mapper.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 1, 'Что означает status=enabled у группы путей в выводе multipath -ll?', '["В группе нет ни одного годного пути", "Группа заблокирована администратором", "Группа резервная: годные пути есть, но ввод-вывод сейчас идёт через active-группу", "Группа работает вместе с active-группой"]', 2, 'Active — группа, через которую идёт ввод-вывод, enabled — резервная, disabled — группа без годных путей. Переключение зависит от failback.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 2, 'Все пути карты отказали в момент 0. Заданы no_path_retry 12 и polling_interval 5. Что происходит с запросом, пришедшим в момент 30, если путь не вернулся?', '["Он сразу получает ошибку", "Он ставится в очередь до момента 60, потом получает ошибку", "Он ждёт вечно", "Он тихо отбрасывается без ошибки"]', 1, 'Число в no_path_retry означает столько интервалов опроса очереди: 12 раз по 5 секунд дают 60. Пока срок не вышел, запросы ждут, потом очередь отключается и они получают ошибки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 3, 'Какая настройка победит при конфликте значений одного параметра?', '["defaults", "devices", "overrides", "multipaths для этого WWID"]', 3, 'Порядок от сильного к слабому: multipaths, overrides, devices, defaults. Раздел multipaths привязан к точному WWID и бьёт даже overrides.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 4, 'Что задаёт iSCSI-параметр replacement_timeout, по умолчанию 120 секунд?', '["Как долго действует пароль CHAP", "Как долго ядро ждёт возвращения сессии, прежде чем вернуть ошибки приложению", "Период обнаружения таргетов", "Время жизни записи в базе узлов"]', 1, 'Это время ожидания восстановления сессии. Пока оно не истекло, ввод-вывод остаётся в очереди; при мультипасе его часто уменьшают, чтобы быстрее переключиться на другой путь.');
